command:
let hero = game.user.character;
if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.getFlag("vagabond-app", "sharpshooter"))?.actor;
}

if (!hero || !hero.getFlag("vagabond-app", "sharpshooter")) return;

const sharpshooter = hero.effects.find(fx => fx.name.toUpperCase() === "SHARPSHOOTER");

if (!sharpshooter){
    const effectData = {
      name: `Sharpshooter`,
      img: "/icons/skills/targeting/crosshair-scope-sniper-green.webp",
      showIcon: 2,
      changes: [
        {
          key: "system.modifiers.skillCheck.ranged.critThreshold",
          type: "add",
          mode: 2,
          value: 1,
          priority: 20
        }
      ]
    };

    await token.actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
}
else {
  token.actor.deleteEmbeddedDocuments("ActiveEffect", [sharpshooter.id]);
}
